COLS = ["aar","antall_linjer","km_taksert","antall_obs","antall_fugl",
        "tetthet","tetthet_minus_se","tetthet_pluss_se","tetthet_cv",
        "tetthet_voksne","voksne_minus_se","voksne_pluss_se",
        "kyllinger_per_par","kyll_minus_se","kyll_pluss_se"]

with open("helgeland_lirype_estimater.csv", "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f)
    w.writerow(["omrade", "rapporteringsnivaa_id"] + COLS)
    for rid, block in ROWS.items():
        for line in block.strip().splitlines():
            w.writerow([OMRADER[rid], rid] + line.split(","))

to_utm = Transformer.from_crs("EPSG:4326", "EPSG:25833", always_xy=True).transform
features, summary = [], []
for rid, polys in POLY.items():
    tot = 0
    for pid, txt in polys:
        g = wkt.loads(txt)
        a = transform(to_utm, g).area / 1e6
        tot += a
        features.append({"type": "Feature", "geometry": mapping(g),
                         "properties": {"omrade": OMRADER[rid], "rapporteringsnivaa_id": rid,
                                        "polygon_id": pid, "areal_km2": round(a, 2)}})
    summary.append((OMRADER[rid], len(polys), round(tot, 1)))

with open("helgeland_takseringsomrader.geojson", "w", encoding="utf-8") as f:
    json.dump({"type": "FeatureCollection",
               "crs": {"type": "name", "properties": {"name": "urn:ogc:def:crs:OGC:1.3:CRS84"}},
               "features": features}, f, ensure_ascii=False)

for s in summary:
    print(s)
